1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Step = { op: string; items?: Item[] };
8	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
9	
10	export type StepResult = { premium: number };
11	export type ScenarioResult = { results: StepResult[] };
12	
13	const BASE_PREMIUMS: Record<string, number> = {
14	  sword: 100,
15	  amulet: 60,
16	  staff: 80,
17	  potion: 40,
18	  rune: 25,
19	  moonstone: 25,
20	};
21	
22	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
23	const PROCESSING_FEE = 5;
24	
25	const CURSE_SURCHARGE_RATE = 0.5;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
28	
29	const BLOCK_SIZE = 3;
30	const BLOCK_BASE_PREMIUM = 60;
31	
32	const countByType = (items: Item[]): Map<string, number> => {
33	  const counts = new Map<string, number>();
34	  for (const item of items) {
35	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
36	  }
37	  return counts;
38	};
39	
40	const basePremiumForType = (type: string, count: number): number =>
41	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
42	
43	const policyBasePremium = (items: Item[]): number =>
44	  [...countByType(items)]
45	    .map(([type, count]) => basePremiumForType(type, count))
46	    .reduce((total, premium) => total + premium, 0);
47	
48	const curseSurcharge = (item: Item): number =>
49	  item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0;
50	
51	const highEnchantmentSurcharge = (item: Item): number =>
52	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
53	    ? BASE_PREMIUMS[item.type] * HIGH_ENCHANTMENT_SURCHARGE_RATE
54	    : 0;
55	
56	const itemModifierSurcharges = (items: Item[]): number =>
57	  items
58	    .map((item) => curseSurcharge(item) + highEnchantmentSurcharge(item))
59	    .reduce((total, surcharge) => total + surcharge, 0);
60	
61	const quotePremium = (items: Item[] = []): number => {
62	  const policyBase = policyBasePremium(items);
63	  const itemSurcharges = itemModifierSurcharges(items);
64	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
65	  return Math.ceil(
66	    policyBase + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
67	  );
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => ({
71	  results: scenario.steps.map((step) => ({
72	    premium: quotePremium(step.items),
73	  })),
74	});
